'use client'

import { useEffect, useId, useRef, useState, type ReactElement, type ReactNode } from 'react'
import { Autocomplete } from '@base-ui/react/autocomplete'
import { Dialog } from '@base-ui/react/dialog'
import { Kbd } from '../atomic-elements/Kbd'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './CommandPalette.module.css'

/** A command or an object: what is typed is matched against `label` and `keywords`. */
export interface CommandPaletteItem {
  value: string
  label: string
  icon?: ReactNode
  /** More words that find it: "bill" for "New invoice". Not shown. */
  keywords?: string[]
  /** Shown right-aligned, one key cap per key: `['⌘', 'N']`. Display only: it does not bind the key. */
  shortcut?: string[]
  disabled?: boolean
  /** Runs when the item is chosen, once the palette has closed and given focus back. */
  onSelect?: () => void
}

/** A titled run of items: Recent, Commands, Customers. A group with no match is left out. */
export interface CommandPaletteGroup {
  label: string
  items: CommandPaletteItem[]
}

export interface CommandPaletteProps {
  groups: CommandPaletteGroup[]
  /** The button that opens it, e.g. a search field in the sidebar. */
  trigger?: ReactElement
  /**
   * The letter that toggles it with ⌘ or Ctrl, anywhere on the page.
   * `false` binds nothing: only one palette on a page should own the key.
   */
  hotkey?: string | false
  /** Called with the chosen item, after its own `onSelect`. */
  onSelect?: (item: CommandPaletteItem) => void
  placeholder?: string
  /** Names the search input. */
  inputLabel?: string
  /** Shown when nothing matches. */
  emptyText?: string
  /** Names the dialog. */
  label?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Trap focus, lock page scroll and make the page inert while open. `false` is for pictures of it. */
  isModal?: boolean
  /** Where it renders instead of `<body>`. */
  container?: HTMLElement | null
  className?: string
}

export function CommandPalette({
  groups,
  trigger,
  hotkey = 'k',
  onSelect,
  placeholder = 'Search commands…',
  inputLabel = 'Search commands',
  emptyText = 'No results',
  label = 'Command palette',
  open,
  defaultOpen = false,
  onOpenChange,
  isModal = true,
  container,
  className,
}: CommandPaletteProps) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen)
  const isOpen = open ?? ownOpen
  const setOpen = (next: boolean) => {
    if (open === undefined) setOwnOpen(next)
    onOpenChange?.(next)
  }
  const hintsId = useId()
  // Accent-insensitive, so "hoa don" finds "Hóa đơn".
  const { contains } = Autocomplete.useFilter({ sensitivity: 'base' })

  // Re-bound every render: the handler reads the current open state.
  useEffect(() => {
    if (!hotkey) return
    const onKey = (e: KeyboardEvent) => {
      if (e.repeat || e.isComposing) return
      if ((e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === hotkey.toLowerCase()) {
        e.preventDefault()
        setOpen(!isOpen)
      }
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  })

  // The choice runs after the close has finished and focus is back on the
  // trigger, so an action that opens a dialog or moves focus keeps it.
  const chosen = useRef<CommandPaletteItem | null>(null)
  const choose = (item: CommandPaletteItem) => {
    chosen.current = item
    setOpen(false)
  }
  const onClosed = (isOpenNow: boolean) => {
    const item = chosen.current
    if (isOpenNow || !item) return
    chosen.current = null
    item.onSelect?.()
    onSelect?.(item)
  }

  return (
    <Dialog.Root open={isOpen} onOpenChange={setOpen} onOpenChangeComplete={onClosed} modal={isModal}>
      {trigger && <Dialog.Trigger render={trigger} />}
      <Dialog.Portal container={container}>
        <Dialog.Backdrop className={styles.backdrop} />
        <Dialog.Viewport className={styles.viewport}>
          <Dialog.Popup className={cn(styles.popup, className)} aria-label={label}>
            {/* inline + open: the list is part of the dialog, not a popup of its own. */}
            <Autocomplete.Root
              items={groups}
              itemToStringValue={(item: CommandPaletteItem) => item.label}
              filter={(item: CommandPaletteItem, query) =>
                [item.label, ...(item.keywords ?? [])].some((text) => contains(text, query))
              }
              open
              inline
              autoHighlight="always"
              keepHighlight
            >
              <Autocomplete.InputGroup className={styles.search}>
                <Icon name="search" className={styles.searchIcon} />
                <Autocomplete.Input
                  className={styles.input}
                  placeholder={placeholder}
                  aria-label={inputLabel}
                  aria-describedby={hintsId}
                />
              </Autocomplete.InputGroup>
              <div className={styles.results}>
                <Autocomplete.Empty className={styles.empty}>{emptyText}</Autocomplete.Empty>
                <Autocomplete.List className={styles.list}>
                  {(group: CommandPaletteGroup) => (
                    <Autocomplete.Group key={group.label} items={group.items} className={styles.group}>
                      <Autocomplete.GroupLabel className={styles.groupLabel}>{group.label}</Autocomplete.GroupLabel>
                      <Autocomplete.Collection>
                        {(item: CommandPaletteItem) => (
                          <Autocomplete.Item
                            key={item.value}
                            value={item}
                            disabled={item.disabled}
                            className={styles.item}
                            onClick={() => choose(item)}
                          >
                            {item.icon && (
                              <span className={styles.icon} aria-hidden="true">
                                {item.icon}
                              </span>
                            )}
                            <span className={styles.label}>{item.label}</span>
                            {/* Shown, not part of the name, as on a Menu item. */}
                            {item.shortcut && <Kbd size="sm" keys={item.shortcut} aria-hidden="true" />}
                          </Autocomplete.Item>
                        )}
                      </Autocomplete.Collection>
                    </Autocomplete.Group>
                  )}
                </Autocomplete.List>
              </div>
              {/* The keys, drawn for sight and said once to a screen reader as the input's description. */}
              <div className={styles.footer}>
                <span id={hintsId} className={styles.visuallyHidden}>
                  Arrow keys to move, Enter to choose, Escape to close.
                </span>
                <span className={styles.hint} aria-hidden="true">
                  <Kbd size="sm" keys={['↑', '↓']} /> Move
                </span>
                <span className={styles.hint} aria-hidden="true">
                  <Kbd size="sm">↵</Kbd> Choose
                </span>
                <span className={styles.hint} aria-hidden="true">
                  <Kbd size="sm">Esc</Kbd> Close
                </span>
              </div>
            </Autocomplete.Root>
          </Dialog.Popup>
        </Dialog.Viewport>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/* The Modal's backdrop and layer: the palette is a dialog like any other. */
.backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay);
  background: var(--scrim);
  transition: opacity var(--duration-fast);
}
.backdrop[data-starting-style],
.backdrop[data-ending-style] {
  opacity: 0;
}

/* Near the top, not centred: the list grows and shrinks as you type, and a
   centred box would jump with it. The input stays where the eye is. */
.viewport {
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: max(var(--space-group), 12dvh) var(--space-group) var(--space-group);
}

/* 40rem: room for a long command name and its shortcut, the Modal lg width
   less a little, as in Linear, Raycast and Spotlight. */
.popup {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  inline-size: 100%;
  max-inline-size: 40rem;
  max-block-size: 100%;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-panel);
  background: var(--popover);
  box-shadow: var(--shadow-xl);
  color: var(--popover-foreground);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  outline: none;
  transition:
    opacity var(--duration-fast),
    scale var(--duration-fast);
}
.popup[data-starting-style],
.popup[data-ending-style] {
  opacity: 0;
  scale: 0.98;
}

/* The search row: taller than a field (box xl, 48px), so it reads as the
   palette's one input. No box of its own: the popup is the box, a rule
   under it ends the row. Its inset is the list's plus an item's, so the
   search icon sits on the same column as the item icons. */
.search {
  --palette-pad: calc(var(--space-stack) + var(--control-md-pad));
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--control-md-gap);
  min-block-size: var(--box-xl);
  padding-inline: var(--palette-pad);
  border-block-end: 1px solid var(--border);
}

.searchIcon {
  flex-shrink: 0;
  font-size: var(--icon-md);
  color: var(--muted-foreground);
}

.input {
  flex: 1;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
  outline: none; /* focus is the caret: the field is the whole popup */
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: var(--text-body-lg);
  line-height: var(--leading-body-lg);
}
.input::placeholder {
  color: var(--muted-foreground);
  opacity: 1;
}

/* About ten rows, then it scrolls; the search row and the hints stay. */
.results {
  --palette-inset: var(--space-stack);
  min-block-size: 0;
  max-block-size: 24rem;
  overflow-y: auto;
  overscroll-behavior: contain;
  scroll-padding-block: var(--palette-inset);
}

.list {
  padding: var(--palette-inset);
}
.list:empty {
  display: none;
}

.group + .group {
  margin-block-start: var(--space-1);
}

/* As a Menu's group label. */
.groupLabel {
  padding: var(--control-xs-pad) var(--control-md-pad) var(--control-xs-gap);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-weight: 500;
  color: var(--muted-foreground);
}

/* As a Menu item: a row of tier md, the corner nested inside the popup's. */
.item {
  display: flex;
  align-items: center;
  gap: var(--control-md-gap);
  min-block-size: var(--control-md);
  padding: var(--space-stack) var(--control-md-pad);
  border-radius: calc(var(--radius-panel) - var(--palette-inset));
  cursor: default;
  user-select: none;
  outline: none;
}
.item[data-highlighted] {
  background: var(--accent);
  color: var(--accent-foreground);
}
.item[data-disabled] {
  color: var(--muted-foreground);
  opacity: 0.6;
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: var(--icon-md);
  font-size: var(--icon-md);
  color: var(--muted-foreground);
}
.item[data-highlighted] .icon {
  color: inherit;
}

.label {
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.empty {
  padding: var(--space-6) var(--control-md-pad);
  color: var(--muted-foreground);
  text-align: center;
}
.empty:empty {
  display: none;
}

/* The keys that work here, quiet, under the list. */
.footer {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-group);
  padding: var(--space-2) calc(var(--space-stack) + var(--control-md-pad));
  border-block-start: 1px solid var(--border);
  font-size: var(--text-body-xs);
  line-height: var(--leading-body-xs);
  color: var(--muted-foreground);
}

.hint {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
}

.visuallyHidden {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Rows are 32px; on touch they grow to 44px, edge to edge. */
@media (pointer: coarse) {
  .item {
    min-block-size: var(--target-coarse);
  }
}
